    if (alignedS2 > HIGH_PERF_SUPPORT_S2_BASIC) {
        notMatched = true;
    }
    if (n2 * g * alignedS1 * alignedS2 * inputDtypeBytes > blockBSizeLimit_ * DATA_TYPE_FP16) {
        notMatched = true;
    }
    if (notMatched) {
        OP_LOGE(context_,
                "[%s]not match template[%s], input params: bn2gs1s2d[%ld, %ld, %ld, %ld, %ld, %ld], "
                "keepProb[%f]",
                templateName,
                expectTemplate.ToString().c_str(),
                inputParams.get_bSize(),
                inputParams.get_n2Size(),
                inputParams.get_gSize(),
                inputParams.get_s1Size(),
                inputParams.get_s2Size(),
                inputParams.get_dSize(),
                inputParams.get_keepProb());
        return false;
    }
    return true;
}

